import dev.ohs.fhir.engine.sync.upload.UploadStrategy
import dev.ohs.fhir.model.r4.terminologies.ResourceType

class App : Application() {
  override fun onCreate() {
    super.onCreate()
    FhirEngineProvider.init(
      FhirEngineConfiguration(
        serverConfiguration = ServerConfiguration(baseUrl = "http://10.0.2.2:8080/fhir/"),
      ),
      this,
    )
    DataCapture.initialize(this)
  }
}

class AppSyncWorker(ctx: Context, params: WorkerParameters) : FhirSyncWorker(ctx, params) {
  override fun getFhirEngine() = FhirEngineProvider.getInstance(applicationContext)

  override fun getDownloadWorkManager() =
    ResourceParamsBasedDownloadWorkManager(
      syncParams = listOf(
        ResourceType.Patient, ResourceType.Encounter, ResourceType.Observation,
        ResourceType.Questionnaire, ResourceType.QuestionnaireResponse,
      ).associateWith { emptyMap<String, String>() },
      context = Timestamps(applicationContext),
    )

  override fun getConflictResolver() = AcceptLocalConflictResolver

  override fun getUploadStrategy() =
    UploadStrategy.forIndividualRequest(
      methodForCreate = HttpCreateMethod.PUT,
      methodForUpdate = HttpUpdateMethod.PATCH,
      squash = true,
    )
}

class Timestamps(private val ctx: Context) : ResourceParamsBasedDownloadWorkManager.TimestampContext {
  private val prefs get() = ctx.getSharedPreferences("sync_timestamps", Context.MODE_PRIVATE)
  override suspend fun saveLastUpdatedTimestamp(resourceType: ResourceType, timestamp: String?) {
    prefs.edit().putString(resourceType.name, timestamp).apply()
  }
  override suspend fun getLasUpdateTimestamp(resourceType: ResourceType): String? =
    prefs.getString(resourceType.name, null)
}
